async function runAgent(task, tools, { maxTurns = 25, maxTokens = 400_000, maxMs = 300_000 } = {}) {
  const t0 = Date.now()
  const messages = [{ role: 'user', content: task }]
  let usedTokens = 0, turns = 0
  const stall = new Map() // name|argsHash -> 连续次数
  const finish = (outcome, reason) => ({
    outcome, reason, turns, usedTokens,
    partial: lastAssistantText(messages), // 部分结果永远保留
  })
  while (true) {
    if (Date.now() - t0 > maxMs) return finish('partial', 'wallclock')
    if (turns >= maxTurns) return finish('partial', 'max_turns')
    const resp = await callModel(messages, tools)
    usedTokens += resp.usage.total_tokens // 信 API 的 usage，别自己估
    if (usedTokens > maxTokens) return finish('partial', 'token_budget')
    messages.push(resp.message)
    const calls = resp.message.tool_calls ?? []
    if (!calls.length) return finish('done', 'model_final')
    const key = calls.map(c => `${c.function.name}|${hash(c.function.arguments)}`).join('+')
    const n = (stall.get(key) ?? 0) + 1; stall.set(key, n)
    if (n >= 3) messages.push({ role: 'system',
      content: `你已经第 ${n} 次重复同样的工具调用且没有新进展：换策略（改参数/换工具），或向用户报告障碍。` })
    messages.push(...await executeToolCalls(calls, tools)) // 见 tools 节点手写题
    turns++
  }
}
